module tb;
    reg clk;
    reg load;
    reg ena;
    reg [1:0] amount;
    reg [63:0] data;
    wire [63:0] q;

    integer errors = 0;
    reg [63:0] expected_q;

    // Instantiate DUT
    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .amount(amount),
        .data(data),
        .q(q)
    );

    // Clock generation
    always #5 clk = ~clk;

    // Task to apply inputs and check output
    task apply_and_check(
        input reg l_val,
        input reg e_val,
        input reg [1:0] amt_val,
        input reg [63:0] d_val
    );
    begin
        load = l_val;
        ena = e_val;
        amount = amt_val;
        data = d_val;

        // Compute expected software model of the register
        if (load) begin
            expected_q = d_val;
        end else if (ena) begin
            case (amt_val)
                2'b00: expected_q = {expected_q[62:0], 1'b0};
                2'b01: expected_q = {expected_q[55:0], 8'b0};
                2'b10: expected_q = {expected_q[63], expected_q[63:1]};
                2'b11: expected_q = {expected_q[63], expected_q[63:8]};
                default: expected_q = expected_q;
            endcase
        end

        @(posedge clk);
        #1; // Allow output to settle

        if (q !== expected_q) begin
            $display("Mismatch! time=%0t | load=%b ena=%b amount=%b data=%h | q=%h expected=%h",
                     $time, load, ena, amount, data, q, expected_q);
            errors = errors + 1;
        end
    end
    endtask

    initial begin
        clk = 0;
        load = 0;
        ena = 0;
        amount = 2'b00;
        data = 64'h0;
        expected_q = 64'h0;

        #12;

        // Test 1: Synchronous Load with positive sign MSB
        apply_and_check(1'b1, 1'b0, 2'b00, 64'h7FFF_FFFF_FFFF_FFFF);

        // Test 2: Shift Left by 1
        apply_and_check(1'b0, 1'b1, 2'b00, 64'h0);

        // Test 3: Shift Left by 8
        apply_and_check(1'b0, 1'b1, 2'b01, 64'h0);

        // Test 4: Load negative number (MSB = 1)
        apply_and_check(1'b1, 1'b0, 2'b00, 64'h8000_0000_0000_0001);

        // Test 5: Arithmetic Shift Right by 1 (should replicate MSB)
        apply_and_check(1'b0, 1'b1, 2'b10, 64'h0);

        // Test 6: Arithmetic Shift Right by 8 (should replicate MSB across 8 bits)
        apply_and_check(1'b0, 1'b1, 2'b11, 64'h0);

        // Test 7: Load with all 1s
        apply_and_check(1'b1, 1'b0, 2'b00, 64'hFFFF_FFFF_FFFF_FFFF);

        // Test 8: Ena = 0, should hold value
        apply_and_check(1'b0, 1'b0, 2'b00, 64'h1234_5678_9ABC_DEF0);

        // Test 9: Priority test (load overrides ena)
        apply_and_check(1'b1, 1'b1, 2'b00, 64'hDEAD_BEEF_CAFE_BABE);

        #20;

        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
